import sys

# These are self-closing tags, require no children. generated by AI.
VOID_TAGS = {
    "area",
    "base",
    "br",
    "col",
    "embed",
    "hr",
    "img",
    "input",
    "link",
    "meta",
    "param",
    "source",
    "track",
    "wbr",
}

# since script and style are present. and had to be handled differently.
RAW_TEXT_TAGS = {"script", "style"}


class ReplacedSoup:
    # A node looks like:
    # {"name": "body", "attrs": {"id": "page"}, "children": [], "selfClosing": False}
    # The root node is named "[document]". Text and comments are nodes too.

    def __init__(self, string_input, parser="html.parser"):
        self.parsed_tree = {}
        if parser == "html.parser":
            self.htmlParser(string_input)
        else:
            self.xmlParser(string_input)

    def findTagContent(self, html_string, startIndex):
        # startIndex is "<". Return the text inside the tag and the
        # index of its ">". A ">" inside a quoted attribute is not the end.
        isQuoted = None  # None means not quoted, chr(34) or chr(39) means quoted
        i = startIndex + 1
        while i < len(html_string):
            char = html_string[i]
            if isQuoted is not None:
                if char == isQuoted:
                    # end of the current quoted string
                    isQuoted = None
            elif char == chr(34) or char == chr(39):
                # ascii for ' is 39 and " is 34
                # start of a quoted string
                isQuoted = char
            elif char == ">":
                # end of the tag. return the content
                return html_string[startIndex + 1 : i], i
            i += 1
        # end of the html. return the content
        return html_string[startIndex + 1 :], -1

    def skipWhitespace(self, text, index):
        # used in between attributes.
        #   to avoid instances like this:
        #   <span id="name1">
        #   <span id = "name1">
        while index < len(text) and text[index].isspace():
            index += 1
        return index

    def parseTagContent(self, tagContent):
        # turn the inside of a tag, such as 'span id="name1" /',
        # into a node. whitespace includes spaces, tabs, and newlines.
        tagContent = tagContent.strip()
        # a trailing slash means the tag closes itself, as in <br />.
        selfClosing = tagContent.endswith("/")
        if selfClosing:
            tagContent = tagContent[:-1].strip()

        # the first word is the tag name. stop at the first space.
        i = 0
        while i < len(tagContent) and not tagContent[i].isspace():
            i += 1
        tagName = tagContent[:i]
        tagAttrs = {}

        while i < len(tagContent):
            # each remaining word is one attribute.
            i = self.skipWhitespace(tagContent, i)
            if i >= len(tagContent):
                break

            nameStart = i
            # the name ends at a space or at "=".
            while (
                i < len(tagContent)
                and not tagContent[i].isspace()
                and tagContent[i] != "="
            ):
                i += 1
            attrName = tagContent[nameStart:i]
            # skip a stray "=" that has no name in front of it.
            if attrName == "":
                i += 1
                continue

            i = self.skipWhitespace(tagContent, i)
            if i < len(tagContent) and tagContent[i] == "=":
                # read the value after "=", allowing spaces around the sign.
                i = self.skipWhitespace(tagContent, i + 1)
                attrValue, i = self.readAttributeValue(tagContent, i)
                tagAttrs[attrName] = attrValue
            else:
                # a name with no "=" is a flag on its own, such as "defer".
                tagAttrs[attrName] = ""

        return {
            "name": tagName,
            "attrs": tagAttrs,
            "children": [],
            "selfClosing": selfClosing,
        }

    def readAttributeValue(self, tagContent, index):
        # Quoted values may contain spaces, as in content="width=device-width, initial-scale=1".
        if index < len(tagContent) and (
            tagContent[index] == chr(34) or tagContent[index] == chr(39)
        ):
            quote = tagContent[index]
            index += 1
            valueStart = index
            while index < len(tagContent) and tagContent[index] != quote:
                index += 1
            attrValue = tagContent[valueStart:index]
            if index < len(tagContent):
                index += 1
            return attrValue, index

        valueStart = index
        while index < len(tagContent) and not tagContent[index].isspace():
            index += 1
        return tagContent[valueStart:index], index

    def closingTagName(self, tagContent):
        # "/div" or "/span\n" both mean the tag name "div" or "span".
        name = tagContent.strip()[1:]
        end = 0
        while end < len(name) and not name[end].isspace():
            end += 1
        return name[:end]

    def appendText(self, htmlStack, textContent):
        # if the text is empty, do nothing
        if textContent.strip() == "":
            return
        # append the text to the last node in the stack
        htmlStack[-1]["children"].append(
            {"name": "text", "attrs": {}, "children": [textContent]}
        )

    def closeMatchingTag(self, htmlStack, closeName):
        # Pop the matching open tag and anything still open inside it.
        # A later </div> must not close whichever node happens to be on top.
        for index in range(len(htmlStack) - 1, 0, -1):
            if htmlStack[index]["name"].lower() == closeName:
                del htmlStack[index:]
                return

    def readRawText(self, html_string, lowerHtml, startIndex, tagName):
        # Copy characters until </script> or </style>, without parsing them.
        closeMarker = "</" + tagName.lower()
        closeIndex = lowerHtml.find(closeMarker, startIndex)
        if closeIndex == -1:
            return html_string[startIndex:], len(html_string)
        return html_string[startIndex:closeIndex], closeIndex

    def htmlParser(self, html_string):
        # every node hangs off this root. The top of the stack is the
        # tag that is still open, so new nodes are added there.
        rootNode = {"name": "[document]", "attrs": {}, "children": []}
        htmlStack = [rootNode]
        # used only to find </script> and </style>. HTML ignores case there.
        lowerHtml = html_string.lower()
        i = 0

        while i < len(html_string):
            if html_string[i] != "<":
                # characters before the next "<" are content, not markup.
                nextStartOfNodeIndex = html_string.find("<", i)
                if nextStartOfNodeIndex == -1:
                    nextStartOfNodeIndex = len(html_string)
                self.appendText(htmlStack, html_string[i:nextStartOfNodeIndex])
                i = nextStartOfNodeIndex
                continue  # skip the rest of the loop and go to the next iteration

            # comments handling
            if html_string.startswith("<!--", i):
                commentEnd = html_string.find("-->", i + 4)
                if commentEnd == -1:
                    commentText = html_string[i + 4 :]
                    i = len(html_string)
                else:
                    commentText = html_string[i + 4 : commentEnd]
                    i = commentEnd + 3
                htmlStack[-1]["children"].append(
                    {"name": "comment", "attrs": {}, "children": [commentText]}
                )
                continue

            # read from this "<" through its ">", then step past it.
            # unclosed "<" means there is nothing left to parse.
            tagContent, tagContentEndIndex = self.findTagContent(html_string, i)
            if tagContentEndIndex == -1:
                break
            i = tagContentEndIndex + 1
            strippedTag = tagContent.strip()

            # <!DOCTYPE> is not an element. bs4 keeps it,
            # so store it as special node, and move on.
            if strippedTag.lower().startswith("!doctype"):
                parts = strippedTag.split(None, 1)
                legacyType = parts[1] if len(parts) > 1 else ""
                doctypeNode = {"name": "!doctype", "attrs": {}, "children": []}
                if legacyType != "":
                    doctypeNode["children"].append(legacyType)
                htmlStack[-1]["children"].append(doctypeNode)
            elif strippedTag.startswith("/"):
                # "</div>" closes that tag and anything still open inside it.
                self.closeMatchingTag(
                    htmlStack, self.closingTagName(strippedTag).lower()
                )
            else:
                currentTag = self.parseTagContent(tagContent)
                if currentTag["name"] == "":
                    continue
                # <br> and <img> never wrap children, even with no "/".
                if currentTag["name"].lower() in VOID_TAGS:
                    currentTag["selfClosing"] = True
                htmlStack[-1]["children"].append(currentTag)
                if currentTag["selfClosing"]:
                    continue
                # leave this tag open so later nodes become its children.
                htmlStack.append(currentTag)
                if currentTag["name"].lower() in RAW_TEXT_TAGS:
                    # <script> and <style> hold raw text until their close tag.
                    rawText, i = self.readRawText(
                        html_string, lowerHtml, i, currentTag["name"]
                    )
                    self.appendText(htmlStack, rawText)

        # Keep the whole document, including text before <html> and after </html>.
        self.parsed_tree = rootNode

    def xmlParser(self):
        return

    def prettifyRecursively(self, node, layers=0):
        # layers is how deep/nested this node is. Each layer is four spaces.
        indent = "    " * layers
        if isinstance(node, str):
            # Drop the spaces that separated this text from nearby tags,
            # then apply one indent so sibling lines start in the same column.
            return f"{indent}{node.strip()}"
        if node["name"] == "[document]":
            # The root is not a tag. Print its children at column 0
            # and leave out any child that rendered as blank.
            parts = []
            for child in node["children"]:
                rendered = self.prettifyRecursively(child, 0).strip("\n")
                if rendered != "":
                    parts.append(rendered)
            return "\n".join(parts)
        if node["name"] == "!doctype":
            # Stored as "!doctype" with a legacy type, such as
            # "html". Write it back in the usual uppercase form.
            legacyType = node["children"][0] if node["children"] else ""
            if legacyType != "":
                return f"{indent}<!DOCTYPE {legacyType}>"
            return f"{indent}<!DOCTYPE>"
        if node["name"] == "text":
            # A text node's children are strings. Recurse so each one
            # is stripped and indented at this same layer.
            return "\n".join(
                self.prettifyRecursively(child, layers) for child in node["children"]
            )
        if node["name"] == "comment":
            # Comments have no attributes or child tags. Put the saved
            # text back between <!-- and -->.
            # incase there are html comments in the html
            commentText = node["children"][0] if node["children"] else ""
            return f"{indent}<!--{commentText}-->"

        # A normal element. Attributes go on the opening line. A void or
        # self-closing tag is one line; anything else wraps indented children.
        attrs = "".join(f' {key}="{value}"' for key, value in node["attrs"].items())
        if node.get("selfClosing"):  # self-closing tags are one line
            return f"{indent}<{node['name']}{attrs} />"
        lines = [f"{indent}<{node['name']}{attrs}>"]  # opening tag
        for child in node["children"]:  # wrap indented children
            lines.append(self.prettifyRecursively(child, layers + 1))
        lines.append(f"{indent}</{node['name']}>")
        return "\n".join(lines)  # join the lines with newlines to make a string

    def prettify(self):
        # recursively call the prettifyRecursively function to prettify the tree
        return self.prettifyRecursively(self.parsed_tree)

    def writeToFile(self, filename):
        with open(filename, "w") as file:
            file.write(self.prettify())

    def __str__(self):
        return str(self.parsed_tree)


def readHTMLFile(filename):
    with open(filename, "r") as file:
        return file.read()


def main(filename):
    html_doc = readHTMLFile(filename)
    soupTree = ReplacedSoup(html_doc, "html.parser")
    soupTree.writeToFile("output.html")  # task 1. write into output.html


if __name__ == "__main__":
    filename = sys.argv[1]
    main(filename)
